import json
from pathlib import Path

lp=Path('lessons.json'); sp=Path('steps.json'); cp=Path('taika/Resourses/taika_basa_course.json')
less=json.loads(lp.read_text(encoding='utf-8')); steps=json.loads(sp.read_text(encoding='utf-8')); catalog=json.loads(cp.read_text(encoding='utf-8'))
long_ids={c['id'] for c in catalog if c.get('category')=='Тайский для долгожителей'}
step_by={s['lesson_id']:s for s in steps['stepsets']}

specs={
'course_long_1':('Иммиграция без паники','Документы, окно, срок и спокойный следующий шаг.', 'Язык для иммиграционного окна; актуальные требования всегда сверяй с официальным офисом.', ['Спросишь, где подать 90-day report и какие документы нужны.','Уточнишь причину отказа без спора и поймёшь следующий шаг.','Оплатишь штраф/квитанцию и проверишь, что взять с собой.','Проведёшь сцену от формы до следующей проверки.']),
'course_long_2':('Банк, переводы и цифровые деньги','Счёт, PromptPay, комиссии и безопасный перевод.', 'Язык для банка и цифровых переводов; никогда не сообщай OTP и проверяй реквизиты в официальном приложении.', ['Откроешь разговор в банке и уточнишь нужные документы.','Спросишь про перевод, QR, курс и комиссию.','Уточнишь, почему перевод не пришёл и какой следующий шаг.','Проведёшь банковскую сцену, не раскрывая коды подтверждения.']),
'course_long_3':('Медицина и страховка','Врач, анализы, аллергии, ассистанс и аптека.', 'Язык для клиники и страховой; это не диагноз — срочные симптомы сразу передавай врачу или в emergency service.', ['Опишешь врачу симптомы, длительность и динамику.','Запишешься на анализы и спросишь о результате.','Предупредишь об аллергии и хронических состояниях.','Проверишь покрытие и попросишь страховую помощь.','Получишь рецепт и уточнишь дозировку у специалиста.']),
'course_long_4':('Транспорт для своих','Мототакси, байк, шлем, страховка и сонгтео.', 'Язык транспорта для Таиланда; язык не заменяет права, шлем, страховку и безопасное решение не ехать.', ['Спросишь цену и маршрут у мототакси или GrabBike.','Проверишь права, залог, страховку и условия аренды.','Попросишь шлем и проверишь базовую безопасность байка.','Уточнишь покрытие при ДТП и исключения полиса.','Проведёшь сцену от аренды до оплаты сонгтео.']),
'course_long_5':('Кондо и правила дома','Шум, общие зоны, мусор и собрание жильцов.', 'Язык для спокойного общения с соседями и управляющей компанией; правила конкретного дома проверяй по объявлению или у juristic office.', ['Попросишь тишины без конфликта и назовёшь время.','Уточнишь правила курения и предложишь разрешённую зону.','Спросишь про парковку, мусор и общие зоны.','Напишешь в condo chat нейтральное сообщение о проблеме.','Поймёшь объявление и примешь участие в собрании.']),
'course_long_6':('Питомцы в Таиланде','Ветклиника, прививки, симптомы, груминг и поездки.', 'Язык для ветеринара и pet-friendly мест; диагноз и схему лечения подтверждает ветеринар.', ['Запишешь питомца к ветеринару и опишешь базовые данные.','Спросишь о прививке, справке и следующей дате.','Опишешь симптомы без самостоятельного диагноза.','Запишешься на груминг и уточнишь уход.','Проверишь правила отеля и перевозки питомца.']),
'course_long_7':('Юмор, мемы и поп-культура','555, чаты, дорамы, TikTok и мягкий подкол.', 'Поп-культурный тайский меняется быстро; проверяй свежесть тренда и используй шутки только там, где есть доверие.', ['Распознаешь 555 и базовую реакцию на шутку в чате.','Поймёшь обращение или сленг из актуального контекста.','Узнаешь реплику из дорамы или TikTok по ситуации.','Спросишь о значении тренда без притворства.','Пошутишь мягко и проверишь реакцию компании.']),
}

# Exact adjustments where the old RU label was wrong, risky, or outside the lesson promise.
updates={
 ('course_long_1_l5',5):dict(ru='Наличные или карта',tip='Уточни способ оплаты до операции; если не уверен, сначала покажи карту или спроси о комиссии.'),
 ('course_long_1_l6',4):dict(ru='Пойти в иммиграцию',thai='ไปตรวจคนเข้าเมือง',phonetic='пай→ туат↘ кон→ кхао→ мыанг↘',tip='Полезная навигационная реплика; конкретные часы и документы проверь в официальном офисе.'),
 ('course_long_2_l6',2):dict(ru='Получить OTP-код',tip='Код вводи только в официальном приложении/терминале и никогда не диктуй его человеку по телефону.'),
 ('course_long_2_l6',3):dict(ru='СМС-код',tip='СМС-код предназначен для подтверждения операции; не пересылай его и не сообщай третьим лицам.'),
 ('course_long_3_l3',4):dict(ru='Аллергии нет',tip='Говори так только если это точно известно; при сомнении сообщи врачу о неизвестной аллергии, а не угадывай.'),
 ('course_long_3_l5',7):dict(ru='Медицинский переводчик',tip='Попроси профессионального переводчика, если не можешь точно описать симптомы или лечение.'),
 ('course_long_4_l6',4):dict(ru='Ехать как местный',tip='Уверенное путешествие не означает риск: сначала проверь маршрут, шлем, права и состояние транспорта.'),
 ('course_long_4_l6',8):dict(ru='Прямо как местный',tip='Локальность — это понимание маршрута и правил, а не отказ от безопасности.'),
 ('course_long_5_l6',6):dict(ru='Договориться мирно',tip='Предложи конкретный следующий шаг и проверь, что сосед/офис его понял.'),
 ('course_long_7_l1',5):dict(ru='В чате пишут 555',tip='555 — чат-код смеха; в голосе скажи обычную реакцию, а не произноси цифры как универсальное правило.'),
 ('course_long_7_l3',2):dict(ru='Узнать реплику на слух',tip='Сначала пойми ситуацию и говорящего; не повторяй реплику, если не знаешь её регистр.'),
 ('course_long_7_l6',2):dict(ru='Собрать шутку для компании',tip='Шути только с теми, кто понимает контекст; не используй внешность, статус, возраст или травму как материал.'),
}
for (lid,order),changes in updates.items():
    for i in step_by[lid]['items']:
        if i.get('order')==order: i.update(changes); break
    else: raise KeyError((lid,order))

for c in less['courses']:
    cid=c['course_id']
    if cid not in long_ids: continue
    title,desc,scope,outcomes=specs[cid]
    c['description']=desc
    c['course_title']=title
    for l in c['lessons']:
        outcome=outcomes[min(l['order']-1,len(outcomes)-1)]
        l['outcomes']=[outcome]
        l['card_count']=len(step_by[l['lesson_id']]['items'])
        l['tags']=['long','paid','scenario','kun-kru']
        l['content']=[
            {'kind':'intro','text':f'Кун Кру покажет, как {l["subtitle"].lower()} — спокойно, конкретно и без лишнего риска.'},
            {'kind':'outline','text':'Сначала поймём ситуацию → затем возьмём живые реплики → в конце соберём следующий шаг.'},
            {'kind':'apply','text':f'Сегодня попробуй сцену «{l["title"]}» вслух: сначала медленно со стрелками, потом естественным темпом.'},
        ]
    for entry in catalog:
        if entry['id']==cid:
            entry['description']=desc
            entry['learning_outcomes']=[{'type':'scenario','count':len(c['lessons'])},{'type':'phrase','count':sum(len(step_by[l['lesson_id']]['items']) for l in c['lessons'])}]

lp.write_text(json.dumps(less,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
sp.write_text(json.dumps({'stepsets':steps['stepsets']},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
cp.write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('updated Long courses',len(long_ids),'lessons',sum(len(c['lessons']) for c in less['courses'] if c['course_id'] in long_ids))
